<?php
// Included only within the administrator's consistent read-only snapshot.
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
require_once __DIR__.'/net-profit-data.php';
$netPolicy=json_decode(queryRows("SELECT value FROM llx_const WHERE entity=$entity AND name='BIMBO_NET_PROFIT_POLICY'")[0]['value'] ?? '{}',true);
$reportData=['ventasLineas'=>[],'pagos'=>[],'compras'=>[],'produccion'=>[]];
foreach(queryRows("SELECT d.fk_facture,d.fk_product,d.qty,d.total_ht,d.buy_price_ht,p.ref,p.label,u.short_label FROM llx_facturedet d JOIN llx_facture f ON f.rowid=d.fk_facture AND f.entity=$entity LEFT JOIN llx_product p ON p.rowid=d.fk_product LEFT JOIN llx_c_units u ON u.rowid=d.fk_unit WHERE f.fk_statut NOT IN(0,3) AND f.type<>4") as $r)$reportData['ventasLineas'][]=['facturaId'=>(int)$r['fk_facture'],'producto'=>$r['label'] ?: 'Línea sin producto','sku'=>$r['ref'] ?: 'SIN-PRODUCTO','cantidad'=>((float)$r['total_ht']<0?-1:1)*abs((float)$r['qty']),'venta'=>(float)$r['total_ht'],'costo'=>$r['buy_price_ht']===null?null:round(((float)$r['total_ht']<0?-1:1)*abs((float)$r['qty'])*(float)$r['buy_price_ht'],2)];
foreach(queryRows("SELECT pf.fk_facture,p.datep,pf.amount,m.code,m.libelle FROM llx_paiement_facture pf JOIN llx_paiement p ON p.rowid=pf.fk_paiement AND p.entity=$entity JOIN llx_facture f ON f.rowid=pf.fk_facture AND f.entity=$entity LEFT JOIN llx_c_paiement m ON m.id=p.fk_paiement") as $r)$reportData['pagos'][]=['facturaId'=>(int)$r['fk_facture'],'fecha'=>day($r['datep']),'importe'=>(float)$r['amount'],'metodo'=>adminPaymentMethod($r)];
foreach(queryRows("SELECT f.rowid,f.ref,f.datef,f.type,f.fk_statut,f.total_ht,f.paye,s.nom FROM llx_facture_fourn f LEFT JOIN llx_societe s ON s.rowid=f.fk_soc AND s.entity=f.entity WHERE f.entity=$entity") as $r)$reportData['compras'][]=['id'=>(int)$r['rowid'],'ref'=>$r['ref'],'fecha'=>day($r['datef']),'proveedor'=>$r['nom'] ?: 'Sin proveedor','total'=>(float)$r['total_ht'],'pagada'=>(bool)$r['paye'],'estado'=>(int)$r['fk_statut'],'tipo'=>(int)$r['type']];
foreach(queryRows("SELECT mo.rowid,mo.ref,mo.status,mo.qty,mo.date_start_planned,mo.date_end_planned,p.label,p.ref sku,u.short_label,COALESCE(SUM(CASE WHEN pr.role='produced' THEN pr.qty ELSE 0 END),0) produced,MAX(CASE WHEN pr.role='produced' THEN sm.datem END) actual_date FROM llx_mrp_mo mo JOIN llx_product p ON p.rowid=mo.fk_product LEFT JOIN llx_c_units u ON u.rowid=p.fk_unit LEFT JOIN llx_mrp_production pr ON pr.fk_mo=mo.rowid AND pr.fk_product=mo.fk_product LEFT JOIN llx_stock_mouvement sm ON sm.rowid=pr.fk_stock_movement WHERE mo.entity=$entity GROUP BY mo.rowid,mo.ref,mo.status,mo.qty,mo.date_start_planned,mo.date_end_planned,p.label,p.ref,u.short_label") as $r)$reportData['produccion'][]=['id'=>(int)$r['rowid'],'ref'=>$r['ref'],'estado'=>(int)$r['status'],'producto'=>$r['label'],'sku'=>$r['sku'],'unidad'=>$r['short_label'] ?: 'Unidad sin definir','previsto'=>(float)$r['qty'],'producido'=>(float)$r['produced'],'fecha'=>day($r['date_start_planned']),'finPrevisto'=>day($r['date_end_planned']),'ultimoMovimiento'=>day($r['actual_date'])];

$reportData['recepciones']=[];
foreach(queryRows("SELECT r.rowid,r.ref,s.nom,r.date_delivery,r.date_reception,r.fk_statut FROM llx_reception r JOIN llx_societe s ON s.rowid=r.fk_soc AND s.entity=r.entity WHERE r.entity=$entity") as $r)$reportData['recepciones'][]=['id'=>(int)$r['rowid'],'ref'=>$r['ref'],'proveedor'=>$r['nom'],'prevista'=>day($r['date_delivery']),'recibida'=>day($r['date_reception']),'estado'=>(int)$r['fk_statut']];

$reportData['gananciaNeta']=$netPolicy ? bimboNetProfit('queryRows',$entity,$netPolicy):[];
